 parts=right if isinstance(right,list) else [right]
 FORMULAS.append(dict(id=f'p-{n}',groups=g if isinstance(g,list) else [g],title=title,left=left,layout=layout,parts=parts,wrong=wrong.split('|'),conditions=condition,tip=tip,explanation=tip,relation='='))
